CREATE OR REPLACE FUNCTION public.check_event_duplicates(candidate jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF;
IF candidate IS NULL OR jsonb_typeof(candidate) <> 'object' OR octet_length(candidate::text)>40000 THEN RAISE EXCEPTION 'Invalid input'; END IF;
SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'title',CASE WHEN e.status='published' OR e.submitter_id=auth.uid() OR public.has_role(auth.uid(),'admin') THEN e.event->>'title' ELSE 'Private submission' END,'date',CASE WHEN e.status='published' OR e.submitter_id=auth.uid() OR public.has_role(auth.uid(),'admin') THEN e.event->>'date' ELSE '' END,'city',CASE WHEN e.status='published' OR e.submitter_id=auth.uid() OR public.has_role(auth.uid(),'admin') THEN e.event->>'city' ELSE '' END,'published',e.status='published','reason',CASE WHEN e.status<>'published' AND e.submitter_id<>auth.uid() AND NOT public.has_role(auth.uid(),'admin') THEN 'Potential match with a private submission - details withheld' WHEN public.normalize_event_text(candidate->>'title')=public.normalize_event_text(e.event->>'title') THEN 'Same title, organizer, date and city' ELSE 'Matching URL or similar event details' END)),'[]'::jsonb) INTO result FROM public.event_records e WHERE e.status IN('published','pending_review','changes_requested') AND (
EXISTS(SELECT 1 FROM unnest(ARRAY[candidate->>'sourceUrl',candidate->>'registrationUrl']) a(url),unnest(ARRAY[e.event->>'sourceUrl',e.event->>'registrationUrl']) b(url) WHERE length(public.normalize_event_url(a.url))>0 AND public.normalize_event_url(a.url)=public.normalize_event_url(b.url))
OR (public.normalize_event_text(candidate->>'organizer')=public.normalize_event_text(e.event->>'organizer') AND candidate->>'date'=e.event->>'date' AND public.normalize_event_text(candidate->>'city')=public.normalize_event_text(e.event->>'city') AND (public.normalize_event_text(candidate->>'title')=public.normalize_event_text(e.event->>'title') OR (length(public.normalize_event_text(candidate->>'title'))>=10 AND position(public.normalize_event_text(candidate->>'title') in public.normalize_event_text(e.event->>'title'))>0))));
RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.check_event_duplicates(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.check_event_duplicates(jsonb) TO authenticated;